mapper.sql:
SELECT t.id AS sourceId, 'transaction' AS sourceType, t.user_id AS userId, t.type AS type, t.amount AS amount, t.original_transaction_id AS originalTransactionId, t.recovery_kind AS recoveryKind, t.reimbursement_amount AS reimbursementAmount, t.currency_code AS currencyCode, t.account_id AS displayAccountId, t.account_id AS originAccountId, NULL AS fundingAccountId, t.category_id AS categoryId, t.transaction_no AS transactionNo, t.title AS title, t.remark AS remark, NULL AS direction, NULL AS recordType, t.from_account_id AS fromAccountId, t.to_account_id AS toAccountId, t.occurred_at AS occurredAt, t.status AS status, t.created_at AS createdAt, t.updated_at AS updatedAt FROM transactions t WHERE t.status = 'normal'
AND t.user_id IN #{uid}
AND t.type = #{type}
AND t.account_id = #{accountId}
AND t.occurred_at >= #{startTime}
AND t.occurred_at < #{endTime}
AND t.account_id IN #{cid}
AND (LOCATE(LOWER(#{search.keyword}), LOWER(COALESCE(t.title, ''))) > 0 OR LOCATE(LOWER(#{search.keyword}), LOWER(COALESCE(t.remark, ''))) > 0)

sql.if:
UNION ALL SELECT d.id AS sourceId, 'debt_record' AS sourceType, d.user_id AS userId, CASE WHEN d.record_type = 'repayment' THEN 'expense' ELSE 'income' END AS type, d.amount AS amount, NULL AS originalTransactionId, NULL AS recoveryKind, 0 AS reimbursementAmount, d.currency_code AS currencyCode, COALESCE(d.funding_account_id, d.account_id) AS displayAccountId, d.account_id AS originAccountId, d.funding_account_id AS fundingAccountId, NULL AS categoryId, NULL AS transactionNo, NULL AS title, d.remark AS remark, d.direction AS direction, d.record_type AS recordType, NULL AS fromAccountId, NULL AS toAccountId, d.occurred_at AS occurredAt, d.status AS status, d.created_at AS createdAt, d.updated_at AS updatedAt FROM debt_records d WHERE d.status = 'active' AND d.direction = 'payable'
AND d.user_id IN #{uid}
AND d.funding_account_id = #{accountId}
AND d.occurred_at >= #{startTime}
AND d.occurred_at < #{endTime}
AND d.funding_account_id IN #{cid}
AND d.record_type = 'borrow'
AND d.record_type = 'repayment'
AND (LOCATE(LOWER(#{search.keyword}), LOWER(CONCAT( COALESCE((SELECT a.name FROM accounts a WHERE a.id = d.account_id), '债务账户'), ' · ', CASE WHEN d.record_type = 'repayment' THEN '还款' ELSE '借入' END))) > 0 OR LOCATE(LOWER(#{search.keyword}), LOWER(COALESCE(d.remark, ''))) > 0)

UNION ALL SELECT h.id AS sourceId, 'human_relation_record' AS sourceType, h.user_id AS userId, CASE WHEN h.direction = 'incoming' THEN 'income' ELSE 'expense' END AS type, h.amount AS amount, NULL AS originalTransactionId, NULL AS recoveryKind, 0 AS reimbursementAmount, h.currency_code AS currencyCode, COALESCE(h.funding_account_id, h.account_id) AS displayAccountId, h.account_id AS originAccountId, h.funding_account_id AS fundingAccountId, NULL AS categoryId, NULL AS transactionNo, NULL AS title, h.remark AS remark, h.direction AS direction, NULL AS recordType, NULL AS fromAccountId, NULL AS toAccountId, h.occurred_at AS occurredAt, h.status AS status, h.created_at AS createdAt, h.updated_at AS updatedAt FROM human_relation_records h WHERE h.status = 'active'
AND h.user_id IN #{uid}
AND h.funding_account_id = #{accountId}
AND h.occurred_at >= #{startTime}
AND h.occurred_at < #{endTime}
AND h.funding_account_id IN #{cid}
AND h.direction = 'incoming'
AND h.direction = 'outgoing'
AND (LOCATE(LOWER(#{search.keyword}), LOWER(CONCAT( COALESCE((SELECT a.name FROM accounts a WHERE a.id = h.account_id), '人情账户'), ' · ', CASE WHEN h.direction = 'incoming' THEN '收到' ELSE '送出' END))) > 0 OR LOCATE(LOWER(#{search.keyword}), LOWER(COALESCE(h.remark, ''))) > 0)

